import xlrd, datetime, glob
# Node 5: find a date cell in samples
for f in sorted(glob.glob('tests/samples/*.xls')):
    try:
        bk = xlrd.open_workbook(f)
    except Exception:
        continue
    for sh in bk.sheets():
        for r in range(sh.nrows):
            for c in range(sh.ncols):
                if sh.cell_type(r,c) == xlrd.XL_CELL_DATE:
                    v = sh.cell_value(r,c)
                    t = xlrd.xldate_as_tuple(v, bk.datemode)
                    print(f, sh.name, r, c, v, t, datetime.datetime(*t), xlrd.xldate_as_datetime(v, bk.datemode))
                    raise SystemExit(0)
print('NO DATE CELLS FOUND in samples')
